{
  "transpose": function(rows: string[]): string[] {
    if (rows.length === 0) return [];
    const maxLen = Math.max(...rows.map(row => row.length));
    const transposed: string[] = [];
    for (let i = 0; i < maxLen; i++) {
      let col = "";
      for (let j = 0; j < rows.length; j++) {
        if (i < rows[j].length) {
          col += rows[j][i];
        }
      }
      transposed.push(col);
    }
    return transposed;
  }
}
